<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import type { Merchant } from '@local/types'; import { api, getData } from '../lib/api'; import { demoMerchant } from '../data/demo'; import { useAuthStore } from '../stores/auth';
const demoMode=import.meta.env.DEV;const emptyMerchant:Merchant={id:'',nameJa:'',status:'ACTIVE',rating:0,reviewCount:0,favoriteCount:0};const route=useRoute();const router=useRouter();const auth=useAuthStore();const merchant=ref<Merchant>(demoMode?demoMerchant:emptyMerchant);const favorite=ref(false);const showInquiry=ref(false);const message=ref('サービスについて詳しく教えてください。');const sent=ref(false);const phone=computed(()=>merchant.value.phone?.replace(/^(0\d)(\d{4})(\d{4})$/,'$1-$2-$3'));
onMounted(async()=>{try{merchant.value=await getData<Merchant>(`/merchants/${String(route.params.id)}`);}catch{if(!demoMode)await router.replace('/search');}});
async function toggleFavorite():Promise<void>{if(!auth.loggedIn){await router.push('/login');return;}try{favorite.value?await api.delete(`/favorites/MERCHANT/${merchant.value.id}`):await api.post('/favorites',{type:'MERCHANT',targetId:merchant.value.id});favorite.value=!favorite.value;}catch{/* keep UI responsive */}}
async function send():Promise<void>{if(!auth.loggedIn){await router.push('/login');return;}try{await api.post('/conversations',{merchantId:merchant.value.id,message:message.value});sent.value=true;}catch{if(demoMode)sent.value=true;}}
</script>
<template><section class="merchant-hero" :style="{backgroundImage:`linear-gradient(90deg,rgba(18,27,24,.85),rgba(18,27,24,.15)),url(${merchant.coverUrl})`}"><div><span class="verified">✓ 本人確認済み</span><h1>{{ merchant.nameJa }}</h1><p>{{ merchant.shortDescriptionJa }}</p><div class="hero-meta"><span>★ {{ Number(merchant.rating).toFixed(1) }} <small>({{ merchant.reviewCount }}件)</small></span><span>⌖ {{ merchant.address?.municipalityName }}</span><span class="open">営業中</span></div></div></section><div class="merchant-nav"><a href="#about">店舗紹介</a><a href="#services">サービス</a><a href="#products">商品</a><a href="#access">アクセス</a></div><section class="merchant-layout"><div class="merchant-content"><section id="about" class="detail-section"><span class="eyebrow">ABOUT</span><h2>店舗紹介</h2><p class="lead">{{ merchant.descriptionJa }}</p><div class="feature-row"><span>✓ 経験豊富なスタッフ</span><span>✓ 中国語・英語対応</span><span>✓ 土曜日も営業</span></div></section><section id="services" class="detail-section"><span class="eyebrow">SERVICES</span><h2>サービス一覧</h2><article v-for="service in merchant.services" :key="service.id" class="service-row"><img :src="service.coverUrl"><div><h3>{{ service.nameJa }}</h3><p>{{ service.summaryJa }}</p><small>{{ service.taxIncluded?'税込':'税別' }}</small></div><strong>{{ service.priceMin?.toLocaleString('ja-JP') }}円<span v-if="service.priceType==='START_FROM'">〜</span></strong></article></section><section v-if="merchant.products?.length" id="products" class="detail-section"><span class="eyebrow">PRODUCTS</span><h2>商品</h2><article v-for="product in merchant.products" :key="product.id" class="service-row"><img :src="product.coverUrl"><div><h3>{{ product.nameJa }}</h3><p>{{ product.summaryJa }}</p></div><strong>{{ product.price?.toLocaleString('ja-JP') }}円</strong></article></section><section id="access" class="detail-section"><span class="eyebrow">ACCESS</span><h2>アクセス・営業時間</h2><div class="map-placeholder"><span>⌖</span><b>{{ merchant.address?.fullAddress }}</b><a :href="`https://maps.google.com/?q=${encodeURIComponent(merchant.address?.fullAddress??'')}`" target="_blank">Google マップで見る ↗</a></div></section></div><aside class="contact-card"><div class="contact-head"><img :src="merchant.logoUrl"><div><b>{{ merchant.nameJa }}</b><small>通常1時間以内に返信</small></div></div><button class="primary" @click="showInquiry=true">✉ 問い合わせる</button><a v-if="merchant.lineUrl" :href="merchant.lineUrl" class="line-button">LINEで問い合わせ</a><a v-if="phone" :href="`tel:${merchant.phone}`" class="phone-button">☎ {{ phone }}</a><button class="save-button" @click="toggleFavorite">{{ favorite?'♥ 保存済み':'♡ お気に入りに保存' }}</button><small class="privacy">相談は無料です。連絡先が公開されることはありません。</small></aside></section><div v-if="showInquiry" class="modal" @click.self="showInquiry=false"><form class="modal-card" @submit.prevent="send"><button type="button" class="close" @click="showInquiry=false">×</button><span class="eyebrow">CONTACT</span><h2>店舗に問い合わせる</h2><p>通常1時間以内に返信します。</p><textarea v-model="message" rows="6"></textarea><button class="primary" :disabled="sent">{{ sent?'送信しました ✓':'メッセージを送る' }}</button></form></div></template>
